AutoEnter.Calculation:
If(

 not IsEmpty( 年 ) and not IsEmpty( 月 );

  年 & Right( "00" & 月; 2 )

)

Let(

[

 v$zero = "000000000000000000000000000000";
 v$zeroLen = Length ( v$zero );


 v$sortNum =
  While (
   [
	v$num = If( not IsEmpty( 並び順 ); 並び順; 1073741823 ) ;  //数字がなかったら一番後ろ
	v$div = 2 ;
	v$result = ""
   ] ;

   v$num <> 0 ; 

   [
	v$result = Mod ( v$num ; v$div ) & v$result ;
	v$num = Div ( v$num  ; v$div )
   ] ;


   v$result

 );

 //桁を揃える
 v$sortNum = Right( v$zero & v$sortNum; v$zeroLen );

 //BOMに変換
 v$sortBom = Substitute ( v$sortNum; [ 0; Char( 8203 ) ]; [ 1; Char( 65279 ) ] );


 v$return = v$sortBom & タグ_カテゴリ::カテゴリ名 & "　" & タグ名

];

v$return

)

Let(
#a = Get ( 日付 );

Date ( Month ( #a ) ; 1 ; Year ( #a ) )

)

Case(
not IsEmpty ( 適用期間_開始日 ) and IsEmpty ( 適用期間_終了日 ) ; Date ( 12 ; 31 ; 2100 );
適用期間_終了日
)

If(

 not IsEmpty( 日付 );

  Year ( 日付 ) & Right( "00" & Month ( 日付 ); 2 )

)

Let ( 

#a = OK日;

Case( 
IsEmpty ( #a ) ; "" ;
Year ( #a ) & Right ( "00" & Month ( #a ) ; 2 )
)

 )

Let ( 

#a = 売上日;

Case( 
IsEmpty ( #a ) ; "" ;
Year ( #a ) & Right ( "00" & Month ( #a ) ; 2 )
)

 )

Let ( 

#a = キャンセル日;

Case( 
IsEmpty ( #a ) ; "" ;
Year ( #a ) & Right ( "00" & Month ( #a ) ; 2 )
)

 )

Let ( 

#a = 撤去日;

Case( 
IsEmpty ( #a ) ; "" ;
Year ( #a ) & Right ( "00" & Month ( #a ) ; 2 )
)

 )

